CREATE COLUMN TABLE "TEST_AP"."OIWB" ("AbsEntry" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50) NOT NULL , "WhsCode" NVARCHAR(8) NOT NULL , "Counted" DECIMAL(21,6) CS_FIXED, "WasCounted" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OIWB_SYSTEM_KEY" ON "TEST_AP"."OIWB" ( "ItemCode" ASC, "WhsCode" ASC )